}

/// Runs scripts/dispatch_and_watch.sh with [args]; [stubFiles] seed the
/// stub-gh fixture dir. Time knobs are shrunk so budget/poll loops resolve
/// in ~1s.
DwRun runDw(
  String name,
  List<String> args,
